layer.css:
@import url("https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:ital,wght@0,400;0,500;0,600;1,400&family=IBM+Plex+Mono:wght@400;500;600;700&display=swap");
[data-ryt="pitch"] { color: rgb(184, 192, 224); background-color: var(--ryt-surface); border-left: 3px solid rgb(198, 160, 246); border-radius: 0px 8px 8px 0px; font-family: var(--ryt-font-body); font-size: 17px; font-weight: 400; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(184, 192, 224); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 3.4px; padding-right: 20.4px; padding-bottom: 3.4px; padding-left: 20.4px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: var(--ryt-muted); border-top: 1px solid var(--ryt-border); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { background-color: var(--ryt-surface); border-top: 1px solid var(--ryt-border); border-right: 1px solid var(--ryt-border); border-bottom: 1px solid var(--ryt-border); border-left: 1px solid var(--ryt-border); border-radius: 10px; transition: transform 0.15s, border-color 0.15s, box-shadow 0.15s }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: rgb(91, 96, 120); text-decoration-thickness: auto; text-underline-offset: 3px; transition: color 0.15s, text-decoration-color 0.15s }
[data-ryt="section"] > h2 { color: var(--ryt-text); border-radius: 0px; font-family: "IBM Plex Mono", ui-monospace, monospace; font-weight: 600; font-style: normal; line-height: 1.3; letter-spacing: -0.32px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="header"] { border-bottom: 1px solid var(--ryt-border); border-top: none }
[data-ryt="nav"] a { color: var(--ryt-header-text); border-radius: 0px; font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 14.72px; font-weight: 400; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: 3px; padding-top: 3.2px; padding-right: 0px; padding-bottom: 3.2px; padding-left: 0px; transition: color 0.15s, text-decoration-color 0.15s }
[data-ryt="button"] { color: rgb(238, 212, 159); background-color: var(--ryt-border); border-top: 1px solid var(--ryt-border); border-right: 1px solid var(--ryt-border); border-bottom: 1px solid var(--ryt-border); border-left: 1px solid var(--ryt-border); border-radius: 8px; font-family: Arial; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(238, 212, 159); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 1px; padding-right: 6px; padding-bottom: 1px; padding-left: 6px; transition: background 0.15s, transform 0.15s }
[data-ryt="review"] { color: var(--ryt-header-text); font-family: var(--ryt-font-body); font-size: 15.2px; font-weight: 400; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: 3px; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: var(--ryt-font-heading); font-size: 13.12px; font-weight: 400; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: 3px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); background-color: var(--ryt-surface); border-top: 1px solid var(--ryt-border); border-right: 1px solid var(--ryt-border); border-bottom: 1px solid var(--ryt-border); border-left: 1px solid var(--ryt-border); border-radius: 10px; font-family: var(--ryt-font-body); font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 3px; transition: transform 0.15s, border-color 0.15s, box-shadow 0.15s; position: relative }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 17.92px; font-weight: 600; font-style: normal; line-height: 1.3; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 3px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"]:hover { color: ZgotmplZ }
[data-ryt="rec-card"] [data-ryt="title"] a::before { content: ""; display: block; position: absolute; width: 3px; height: 128.484px; color: var(--ryt-text); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 3px; font-family: var(--ryt-font-body); font-size: 17px; font-weight: 400; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 3px; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-text); top: 9.6px; left: 0px }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: #c6a0f6; text-decoration-color: #c6a0f6; transform: translateX(3px); box-shadow: 0 8px 24px rgba(17, 18, 27, 0.45) }
[data-ryt="button"]:hover { transform: rotate(12deg) }
[data-ryt="nav"] a::before { content: "./"; display: inline; color: rgb(110, 115, 141); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 14.72px; font-weight: 400; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(110, 115, 141); text-decoration-thickness: auto; text-underline-offset: 3px; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: rgb(110, 115, 141) }
[data-ryt="nav"] a:hover { color: #c6a0f6; text-decoration-color: #c6a0f6; color: #f5a97f }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: #c6a0f6; text-decoration-color: #c6a0f6 }
article[data-ryt="rec-card"]:hover { color: #c6a0f6; text-decoration-color: #c6a0f6; transform: translateX(3px); box-shadow: 0 8px 24px rgba(17, 18, 27, 0.45) }
